// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

contract CoursePayment {
    address public refundManager;

    mapping(address => uint256) public paidAmount;
    mapping(address => bool) public hasAccess;

    event CoursePaid(address indexed student, uint256 amount);
    event AccessRevoked(address indexed student);
    event Refunded(address indexed student, uint256 amount);

    modifier onlyRefundManager() {
        require(msg.sender == refundManager, "Not refund manager");
        _;
    }

    constructor() {
        refundManager = msg.sender;
    }

    // Оплата курсу
    function payForCourse() external payable {
        require(msg.value > 0, "Payment must be > 0");
        require(!hasAccess[msg.sender], "Access already granted");

        paidAmount[msg.sender] = msg.value;
        hasAccess[msg.sender] = true;

        emit CoursePaid(msg.sender, msg.value);
    }

    function checkAccess(address user) external view returns (bool) {
        return hasAccess[user];
    }

    // Викликається ТІЛЬКИ RefundManager
    function refund(address student) external onlyRefundManager {
        require(hasAccess[student], "No access");

        uint256 amount = paidAmount[student];

        hasAccess[student] = false;
        paidAmount[student] = 0;

        (bool ok, ) = payable(student).call{value: amount}("");
        require(ok, "Refund failed");

        emit AccessRevoked(student);
        emit Refunded(student, amount);
    }
}
